import{V as e,ht as t,nt as n,tt as r}from"./chunks/framework.wxcks8ca.js";var i=JSON.parse(`{"title":"在 IDE 中使用","description":"","frontmatter":{},"headers":[],"relativePath":"kimi-code-cli/guides/ides.md","filePath":"zh/kimi-code-cli/guides/ides.md"}`),a={name:`kimi-code-cli/guides/ides.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="在-ide-中使用" tabindex="-1">在 IDE 中使用 <a class="header-anchor" href="#在-ide-中使用" aria-label="Permalink to “在 IDE 中使用”">​</a></h1><p>Kimi Code CLI 支持通过 <a href="https://agentclientprotocol.com/" target="_blank" rel="noreferrer">Agent Client Protocol (ACP)</a> 集成到 IDE 中，让你在编辑器内直接使用 AI 辅助编程。</p><h2 id="前置准备" tabindex="-1">前置准备 <a class="header-anchor" href="#前置准备" aria-label="Permalink to “前置准备”">​</a></h2><p>在配置 IDE 之前，请确保已安装 Kimi Code CLI 并完成登录配置。</p><p>ACP 适配层暴露子命令 <code>kimi acp</code>，IDE 通过子进程方式启动它，并在标准输入/输出上跑 JSON-RPC。每次 IDE 创建会话时，CLI 会复用它的鉴权状态——不需要重复登录。</p><div class="tip custom-block"><p class="custom-block-title">路径提示</p><p>macOS 下从 IDE GUI 启动的子进程通常<strong>不会</strong>继承终端 shell 的 <code>PATH</code>，所以如果 <code>kimi</code> 不在 <code>/usr/local/bin</code> 这类系统目录里，IDE 配置中要使用绝对路径。终端里运行 <code>which kimi</code> 可以查到当前生效的路径。</p></div><h2 id="在-zed-中使用" tabindex="-1">在 Zed 中使用 <a class="header-anchor" href="#在-zed-中使用" aria-label="Permalink to “在 Zed 中使用”">​</a></h2><p><a href="https://zed.dev/" target="_blank" rel="noreferrer">Zed</a> 是一个原生支持 ACP 的现代编辑器。</p><p>在 Zed 的配置文件 <code>~/.config/zed/settings.json</code> 中添加：</p><div class="language-json"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;agent_servers&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;Kimi Code CLI&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;type&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;custom&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;command&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;kimi&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;args&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;acp&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">],</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;env&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {}</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>配置说明：</p><ul><li><code>type</code>：固定值 <code>&quot;custom&quot;</code></li><li><code>command</code>：Kimi Code CLI 的可执行路径。如果 <code>kimi</code> 不在 PATH 中，请使用完整路径（例如 <code>/Users/you/.local/bin/kimi</code>）。</li><li><code>args</code>：启动参数。<code>acp</code> 子命令切换到 ACP 模式。</li><li><code>env</code>：附加环境变量，通常留空即可。Zed 会自动注入一份默认环境。</li></ul><p>保存配置后，在 Zed 的 Agent 面板里新建一次对话，就会以你刚才配置的 <code>Kimi Code CLI</code> 启动一个 ACP 子进程。Zed 在 <code>agent_servers</code> 这层声明的 MCP 服务也会通过 ACP 协议转发到 kimi 这一侧。</p><h2 id="在-jetbrains-ide-中使用" tabindex="-1">在 JetBrains IDE 中使用 <a class="header-anchor" href="#在-jetbrains-ide-中使用" aria-label="Permalink to “在 JetBrains IDE 中使用”">​</a></h2><p>JetBrains 系列 IDE（IntelliJ IDEA、PyCharm、WebStorm 等）通过 AI 聊天插件支持 ACP。</p><p>如果没有 JetBrains AI 订阅，可以在注册表中启用 <code>llm.enable.mock.response</code>，便于在仅使用 ACP 的场景里访问 AI 聊天面板。连按两次 Shift 搜索 &quot;Registry / 注册表&quot; 即可打开。</p><p>在 AI 聊天面板的菜单中点击 &quot;Configure ACP agents&quot;，添加以下配置：</p><div class="language-json"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;agent_servers&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;Kimi Code CLI&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;command&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;~/.local/bin/kimi&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;args&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;acp&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">],</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;env&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {}</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>JetBrains 这一侧对 <code>command</code> 字段处理较严格——务必填写<strong>绝对路径</strong>，可以在终端执行 <code>which kimi</code> 拿到。保存后，AI 聊天的 Agent 选择器里就会出现 <code>Kimi Code CLI</code>。</p><h2 id="在-paseo-中使用" tabindex="-1">在 Paseo 中使用 <a class="header-anchor" href="#在-paseo-中使用" aria-label="Permalink to “在 Paseo 中使用”">​</a></h2><p><a href="https://paseo.sh/" target="_blank" rel="noreferrer">Paseo</a> 是一个自托管的编排器，能在桌面、网页和手机上统一启动并接管各类 agent 的 CLI。它和 IDE 一样，通过 ACP 接入 Kimi Code CLI。</p><p>在 Paseo 内置的 ACP provider 目录里选择 <strong>Kimi Code CLI</strong>，或在 <code>~/.paseo/config.json</code> 里添加一个自定义 provider：</p><div class="language-json"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;agents&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;providers&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;kimi&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">        &quot;extends&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;acp&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">        &quot;label&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Kimi Code CLI&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">        &quot;command&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;kimi&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;acp&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">      }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>Paseo 的通用 ACP 适配层不会帮你走登录流程，所以请先完成终端登录（见<a href="#前置准备">前置准备</a>）——否则创建会话会以 <code>Authentication required</code> 失败。</p><h2 id="故障排查" tabindex="-1">故障排查 <a class="header-anchor" href="#故障排查" aria-label="Permalink to “故障排查”">​</a></h2><ul><li><strong>会话立刻被中断 / IDE 提示 &quot;agent exited&quot;</strong>：通常是 <code>command</code> 路径不对或 kimi 没登录。先在终端跑一次 <code>kimi acp</code> 验证：如果阻塞等待标准输入则说明 CLI 本身没问题，问题在 IDE 配置；如果立刻报错则按报错提示处理（多数是没 <code>/login</code>）。</li><li><strong>IDE 显示 &quot;auth required&quot;</strong>：表示 CLI 没有可用的鉴权令牌。退出 IDE，在终端执行 <code>kimi</code> 完成登录后再启动 IDE 即可。</li><li><strong>MCP 工具看不到</strong>：参考 <a href="/code/docs/kimi-code-cli/reference/kimi-acp.html"><code>kimi acp</code></a> 中的能力表确认 IDE 配的 MCP 传输类型是否被支持。当前 Kimi Code CLI 的 ACP 适配层支持 <code>http</code>、<code>stdio</code> 与 <code>sse</code> 三种传输方式；<code>acp</code> 传输的 MCP server 会被静默丢弃并在日志中给出 warn。</li></ul><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to “下一步”">​</a></h2><ul><li><a href="/code/docs/kimi-code-cli/reference/kimi-acp.html">kimi acp 参考</a> — ACP 能力矩阵和方法覆盖详情</li><li><a href="/code/docs/kimi-code-cli/reference/kimi-command.html">kimi 命令参考</a> — 完整子命令列表</li></ul>`,28)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};